package com.aistock.prediction.question;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
class QuestionAnswerTemplateTest {
 @Test void matchesDefinitionWithSameIndicator(){var f=QuestionFacts.build(QuestionSamples.analysis(false),"均线？","test",QuestionSamples.M).values();var good=QuestionSamples.raw("INDICATOR","{{QA_MA_DEF}}。{{MA5_STATE}}。","QA_MA_DEF","MA5_STATE");assertEquals("ANSWERED",QuestionAnswerTemplate.render(good,f,QuestionSamples.M).status());assertThrows(com.aistock.common.BusinessException.class,()->QuestionAnswerTemplate.render(QuestionSamples.raw("INDICATOR","{{QA_MA_DEF}}。{{RSI_STATE}}。","QA_MA_DEF","RSI_STATE"),f,QuestionSamples.M));}
 @Test void refusesMissingPredictionAndMalformedScope() throws Exception {var f=QuestionFacts.build(QuestionSamples.analysis(false),"预测？","test",QuestionSamples.M).values();var scope=QuestionSamples.M.readTree("{\"status\":\"OUT_OF_SCOPE\",\"topic\":\"LIMITATION\",\"paragraphs\":[]}");assertEquals("OUT_OF_SCOPE",QuestionAnswerTemplate.render(scope,f,QuestionSamples.M).status());assertThrows(com.aistock.common.BusinessException.class,()->QuestionAnswerTemplate.render(QuestionSamples.raw("PREDICTION","{{PRED_TREND}}。","PRED_TREND"),f,QuestionSamples.M));((ObjectNode)scope).put("extra","evil");assertThrows(com.aistock.common.BusinessException.class,()->QuestionAnswerTemplate.render(scope,f,QuestionSamples.M));}
 @Test void unsafeLiteralAndWrongPredictionTopicAreRejected(){var f=QuestionFacts.build(QuestionSamples.analysis(true),"风险？","test",QuestionSamples.M).values();for(String literal:new String[]{"价格99元","已经金叉","<img>","保证收益"})assertThrows(com.aistock.common.BusinessException.class,()->QuestionAnswerTemplate.render(QuestionSamples.raw("RISK",literal+"{{BASIS_LIMIT}}。","BASIS_LIMIT"),f,QuestionSamples.M));assertThrows(com.aistock.common.BusinessException.class,()->QuestionAnswerTemplate.render(QuestionSamples.raw("RISK","{{PRED_P1}}。","PRED_P1"),f,QuestionSamples.M));}
}
